INSERT INTO quizzes (id, topic_id, title, title_hi, total_questions, time_limit_mins, is_premium, difficulty, is_previous_year, description, description_hi)
VALUES (1303, 1199, 'Forest Policy & Conservation – Minor Forest Produce Master Quiz', 'वन नीति एवं संरक्षण – लघु वनोपज मास्टर क्विज़', 10, 10, 0, 'medium', 0, 'Master quiz on minor forest produce and conservation policies in Chhattisgarh.', 'छत्तीसगढ़ में लघु वनोपज और संरक्षण नीतियों पर मास्टर क्विज़।');

INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES
(1303, 1199, 'According to the official policy of the Chhattisgarh Government, which of the following is considered an UN-NATIONALIZED (Arashtriyakrit) minor forest produce?', 'छत्तीसगढ़ सरकार की आधिकारिक नीति के अनुसार, निम्नलिखित में से किसे ''अराष्ट्रीयकृत'' (Un-nationalized) लघु वनोपज माना जाता है?', 'Tendu Patta', 'तेंदूपत्ता', 'Kullu Gum (Gond)', 'कुल्लू गोंद', 'Dhawda Gum (Gond)', 'धवड़ा गोंद', 'Sal Seed (Beej)', 'साल बीज', 4, 'According to Chhattisgarh''s specific policy on Minor Forest Produce, there are exactly 3 Nationalized MFPs: Tendu Patta, Dhawda Gond, and Kullu Gond. Products like Sal Beej, Harra Beej, and Imli are Un-nationalized.', 'छत्तीसगढ़ की लघु वनोपज संबंधी विशिष्ट नीति के अनुसार, ठीक 3 राष्ट्रीयकृत लघु वनोपज हैं: तेंदूपत्ता, धवड़ा गोंद और कुल्लू गोंद। साल बीज, हर्रा बीज और इमली जैसे उत्पाद अराष्ट्रीयकृत हैं।', 1),
(1303, 1199, 'What is the revised remuneration rate per ''Standard Bag'' (Manak Bora) for Tendu leaf collectors in Chhattisgarh for the collection season 2024-25?', 'संग्रहण सत्र 2024-25 के लिए छत्तीसगढ़ में तेंदूपत्ता संग्राहकों के लिए प्रति ''मानक बोरा'' (Standard Bag) संशोधित पारिश्रमिक दर क्या है?', 'Rs. 4000', '4000 रुपये', 'Rs. 5500', '5500 रुपये', 'Rs. 6000', '6000 रुपये', 'Rs. 2500', '2500 रुपये', 2, 'The remuneration rate for Tendu leaf collectors was increased from Rs. 4000 to Rs. 5500 per standard bag by the state government for the collection season of 2024-25.', 'राज्य सरकार द्वारा 2024-25 के संग्रहण सत्र के लिए तेंदूपत्ता संग्राहकों की पारिश्रमिक दर 4000 रुपये से बढ़ाकर 5500 रुपये प्रति मानक बोरा कर दी गई है।', 2),
(1303, 1199, 'How many types of minor forest produces (MFP) are currently being procured at the Minimum Support Price (MSP) by the Chhattisgarh government?', 'वर्तमान में छत्तीसगढ़ सरकार द्वारा न्यूनतम समर्थन मूल्य (MSP) पर कितने प्रकार के लघु वनोपजों की खरीद की जा रही है?', '34', '34', '52', '52', '61', '61', '67', '67', 4, 'To prevent the exploitation of tribals and ensure fair prices, the Chhattisgarh State Minor Forest Produce Federation currently procures exactly 67 items of minor forest produce at Minimum Support Price.', 'आदिवासियों के शोषण को रोकने और उचित मूल्य सुनिश्चित करने के लिए, छत्तीसगढ़ राज्य लघु वनोपज संघ वर्तमान में न्यूनतम समर्थन मूल्य पर ठीक 67 प्रकार के लघु वनोपजों की खरीद करता है।', 3),
(1303, 1199, 'Consider the following statements about the ''Shaheed Mahendra Karma Tendu Patta Sangrahak Samajik Suraksha Yojana'':

1. It was launched on 5 August 2020.
2. The financial grant for the scheme is fully (100%) funded by the State Forest Department.
3. In the event of the normal death of a registered collector (under 50 years of age), a grant of Rs. 2 lakh is provided.

Which of the statements given above is/are correct?', '''शहीद महेंद्र कर्मा तेंदूपत्ता संग्राहक सामाजिक सुरक्षा योजना'' के बारे में निम्नलिखित कथनों पर विचार करें:

1. इसे 5 अगस्त 2020 को लॉन्च किया गया था।
2. योजना के लिए वित्तीय अनुदान पूरी तरह से (100%) राज्य वन विभाग द्वारा वित्त पोषित है।
3. पंजीकृत संग्राहक (50 वर्ष से कम आयु) की सामान्य मृत्यु की स्थिति में 2 लाख रुपये का अनुदान प्रदान किया जाता है।

ऊपर दिए गए कथनों में से कौन सा/से सही है/हैं?', '1 and 2 only', 'केवल 1 और 2', '2 and 3 only', 'केवल 2 और 3', '1 and 3 only', 'केवल 1 और 3', '1, 2, and 3', '1, 2, और 3', 3, 'Statement 2 is incorrect because the scheme''s grant is funded jointly: 50% by the Chhattisgarh Forest Department and 50% by the State Minor Forest Produce Federation. Statements 1 and 3 are factually correct.', 'कथन 2 गलत है क्योंकि योजना का अनुदान संयुक्त रूप से वित्त पोषित है: 50% छत्तीसगढ़ वन विभाग द्वारा और 50% राज्य लघु वनोपज संघ द्वारा। कथन 1 और 3 तथ्यात्मक रूप से सही हैं।', 4),
(1303, 1199, 'In the context of the minor forest produce trade in Chhattisgarh, exactly how many leaves constitute one ''Standard Bag'' (Manak Bora) of Tendu leaves?', 'छत्तीसगढ़ में लघु वनोपज व्यापार के संदर्भ में, तेंदूपत्ते के एक ''मानक बोरा'' (Standard Bag) में ठीक कितने पत्ते होते हैं?', '10,000 leaves', '10,000 पत्ते', '25,000 leaves', '25,000 पत्ते', '50,000 leaves', '50,000 पत्ते', '1,00,000 leaves', '1,00,000 पत्ते', 3, 'A ''Manak Bora'' (Standard Bag) is the official unit of measurement for Tendu leaves. It consists of exactly 50,000 leaves, bundled systematically as 1,000 packets containing 50 leaves each.', '''मानक बोरा'' तेंदूपत्ते के मापन की आधिकारिक इकाई है। इसमें ठीक 50,000 पत्ते होते हैं, जिन्हें 50-50 पत्तों के 1,000 पैकेटों के रूप में व्यवस्थित रूप से बांधा जाता है।', 5),
(1303, 1199, 'When did the ''Chhattisgarh State Minor Forest Produce (Trading and Development) Cooperative Federation'' officially come into existence?', '''छत्तीसगढ़ राज्य लघु वनोपज (व्यापार एवं विकास) सहकारी संघ'' आधिकारिक तौर पर कब अस्तित्व में आया?', '31 October 2000', '31 अक्टूबर 2000', '1 November 2000', '1 नवंबर 2000', '1 May 2001', '1 मई 2001', '28 July 2004', '28 जुलाई 2004', 1, 'The Chhattisgarh State Minor Forest Produce Federation was formed on 31 October 2000, exactly one day before the state''s official formation, through the bifurcation of the Madhya Pradesh Minor Forest Produce Federation (formed in 1984).', 'छत्तीसगढ़ राज्य लघु वनोपज संघ का गठन 31 अक्टूबर 2000 को, राज्य के आधिकारिक गठन से ठीक एक दिन पहले, मध्य प्रदेश लघु वनोपज संघ (1984 में गठित) के विभाजन के माध्यम से किया गया था।', 6),
(1303, 1199, 'Match the following tribal communities with their traditional occupations heavily reliant on minor forest produce:

List-I (Tribe)
(a) Khairwar
(b) Kamar
(c) Shikari
(d) Baiga

List-II (Occupation)
(i) Extracting Katha from Khair trees
(ii) Bamboo crafts and basket weaving
(iii) Making mats and brooms from Chhind leaves
(iv) Traditional healing using medicinal herbs

Codes:', 'लघु वनोपज पर अत्यधिक निर्भर पारंपरिक व्यवसायों के साथ निम्नलिखित आदिवासी समुदायों को सुमेलित करें:

सूची-I (जनजाति)
(a) खैरवार
(b) कमार
(c) शिकारी
(d) बैगा

सूची-II (व्यवसाय)
(i) खैर के पेड़ों से कत्था निकालना
(ii) बांस शिल्प और टोकरी बुनाई
(iii) छिंद के पत्तों से चटाई और झाड़ू बनाना
(iv) औषधीय जड़ी-बूटियों का उपयोग करके पारंपरिक उपचार

कूट:', '(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)', '(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)', '(a)-(i), (b)-(iii), (c)-(ii), (d)-(iv)', '(a)-(i), (b)-(iii), (c)-(ii), (d)-(iv)', '(a)-(ii), (b)-(i), (c)-(iv), (d)-(iii)', '(a)-(ii), (b)-(i), (c)-(iv), (d)-(iii)', '(a)-(iv), (b)-(ii), (c)-(iii), (d)-(i)', '(a)-(iv), (b)-(ii), (c)-(iii), (d)-(i)', 1, 'The correct matches are: Khairwar extracts Katha (Surguja), Kamar is renowned for Bamboo crafts (Gariaband), Shikari tribe makes products from Chhind leaves, and Baiga serves as traditional healers (medicine men/Gunia).', 'सही सुमेलन हैं: खैरवार कत्था (सरगुजा) निकालते हैं, कमार बांस शिल्प (गरियाबंद) के लिए प्रसिद्ध हैं, शिकारी जनजाति छिंद के पत्तों से उत्पाद बनाती है, और बैगा पारंपरिक चिकित्सक (गुनिया) के रूप में कार्य करते हैं।', 7),
(1303, 1199, 'Consider the following statements regarding Tendu leaf production in Chhattisgarh:

1. It is popularly referred to as the ''Green Gold'' (Hara Sona) of the state.
2. Chhattisgarh contributes approximately 17% to the total Tendu leaf production of India.
3. The Bastar and Surguja divisions are the primary regions for its collection.

Which of the statements given above is/are correct?', 'छत्तीसगढ़ में तेंदूपत्ता उत्पादन के संबंध में निम्नलिखित कथनों पर विचार करें:

1. इसे राज्य का ''हरा सोना'' (Green Gold) कहा जाता है।
2. छत्तीसगढ़ भारत के कुल तेंदूपत्ता उत्पादन में लगभग 17% का योगदान देता है।
3. बस्तर और सरगुजा संभाग इसके संग्रहण के प्राथमिक क्षेत्र हैं।

ऊपर दिए गए कथनों में से कौन सा/से सही है/हैं?', '1 and 2 only', 'केवल 1 और 2', '2 and 3 only', 'केवल 2 और 3', '1 and 3 only', 'केवल 1 और 3', '1, 2, and 3', '1, 2, और 3', 4, 'All statements are correct. Tendu leaf (used for Bidi rolling) is called Hara Sona. Chhattisgarh produces roughly 17% of India''s Tendu leaves, with Bastar and Surguja being the major collection hubs.', 'सभी कथन सही हैं। तेंदूपत्ता (बीड़ी बनाने के लिए प्रयुक्त) को हरा सोना कहा जाता है। छत्तीसगढ़ भारत के लगभग 17% तेंदूपत्ते का उत्पादन करता है, जिसमें बस्तर और सरगुजा प्रमुख संग्रहण केंद्र हैं।', 8),
(1303, 1199, 'Assertion (A): In Chhattisgarh, the Bamboo tree (Bans) is often culturally referred to as the ''Green Gold of Tribals'' (Adivasiyon ka Hara Sona).

Reason (R): Bamboo plays a pivotal role in the tribal economy, accounting for roughly 20% of the minor forest produce revenue and providing livelihood to tribes like Kamar, Dhanwar, and Birhor.

Codes:', 'कथन (A): छत्तीसगढ़ में, बांस के पेड़ को अक्सर सांस्कृतिक रूप से ''आदिवासियों का हरा सोना'' कहा जाता है।

कारण (R): बांस आदिवासी अर्थव्यवस्था में एक महत्वपूर्ण भूमिका निभाता है, जो लघु वनोपज राजस्व का लगभग 20% हिस्सा है और कमार, धनवार और बिरहोर जैसी जनजातियों को आजीविका प्रदान करता है।

कूट:', 'Both (A) and (R) are true and (R) is the correct explanation of (A)', '(A) और (R) दोनों सही हैं और (R), (A) का सही स्पष्टीकरण है', 'Both (A) and (R) are true but (R) is NOT the correct explanation of (A)', '(A) और (R) दोनों सही हैं लेकिन (R), (A) का सही स्पष्टीकरण नहीं है', '(A) is true but (R) is false', '(A) सही है लेकिन (R) गलत है', '(A) is false but (R) is true', '(A) गलत है लेकिन (R) सही है', 1, 'While Tendu Leaf is simply called ''Hara Sona'', Bamboo is distinctly called ''Adivasiyon ka Hara Sona''. Reason (R) perfectly explains this status, as bamboo forms the backbone of the tribal craft economy and minor forest revenue.', 'जबकि तेंदूपत्ते को केवल ''हरा सोना'' कहा जाता है, बांस को विशिष्ट रूप से ''आदिवासियों का हरा सोना'' कहा जाता है। कारण (R) इस स्थिति की पूरी तरह से व्याख्या करता है, क्योंकि बांस आदिवासी शिल्प अर्थव्यवस्था और लघु वन राजस्व की रीढ़ है।', 9),
(1303, 1199, 'Match the following minor forest produces with their primary commercial applications/derivatives:

List-I
(a) Harra
(b) Katha
(c) Lac
(d) Tendu Patta

List-II
(i) Leather tanning and Ayurvedic medicines (Triphala)
(ii) Edible ingredient in Paan, extracted from Khair tree
(iii) Varnish, paints, and bangle manufacturing
(iv) Bidi rolling industry

Codes:', 'निम्नलिखित लघु वनोपजों को उनके प्राथमिक व्यावसायिक अनुप्रयोगों/उत्पादों के साथ सुमेलित करें:

सूची-I
(a) हर्रा
(b) कत्था
(c) लाख
(d) तेंदूपत्ता

सूची-II
(i) चमड़ा कमाना और आयुर्वेदिक दवाएं (त्रिफला)
(ii) पान में खाने योग्य सामग्री, खैर के पेड़ से निकाला गया
(iii) वार्निश, पेंट और चूड़ी निर्माण
(iv) बीड़ी निर्माण उद्योग

कूट:', '(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)', '(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)', '(a)-(ii), (b)-(i), (c)-(iii), (d)-(iv)', '(a)-(ii), (b)-(i), (c)-(iii), (d)-(iv)', '(a)-(i), (b)-(iii), (c)-(ii), (d)-(iv)', '(a)-(i), (b)-(iii), (c)-(ii), (d)-(iv)', '(a)-(iii), (b)-(ii), (c)-(i), (d)-(iv)', '(a)-(iii), (b)-(ii), (c)-(i), (d)-(iv)', 1, 'The correct applications are: Harra is extensively used for leather tanning and Triphala powder. Katha is extracted from the Khair tree. Lac (secreted by insects on Palash/Kusum trees) is used in bangles/paints. Tendu leaves are exclusively used for making Bidis.', 'सही अनुप्रयोग हैं: हर्रा का उपयोग चमड़ा कमाने और त्रिफला चूर्ण के लिए बड़े पैमाने पर किया जाता है। खैर के पेड़ से कत्था निकाला जाता है। लाख (पलाश/कुसुम के पेड़ों पर कीड़ों द्वारा स्रावित) का उपयोग चूड़ियों/पेंट्स में किया जाता है। तेंदूपत्ते का उपयोग विशेष रूप से बीड़ी बनाने के लिए किया जाता है।', 10);
